def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        # Chunk conversion also supports literals beyond Python's digit limit.
        sign = -1 if text.startswith("-") else 1
        if text[:1] in ("+", "-"):
            text = text[1:]
        value = 0
        for start in range(0, len(text), 500):
            chunk = text[start:start + 500]
            value = value * 10 ** len(chunk) + int(chunk)
        return sign * value

    def parse(formula):
        tokens = re.findall(
            r"\d+|[A-Z]+\d*|<>|<=|>=|[^\s]", formula
        )
        operands = []
        operators = []
        need_operand = True

        def reduce_one():
            op = operators.pop()
            if op == "neg":
                operands.append((op, operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append((op, left, right))

        for index, token in enumerate(tokens):
            if token in functions:
                continue

            if token[0].isdigit():
                operands.append(integer(token))
                need_operand = False

            elif token[0].isalpha():
                operands.append(token)
                need_operand = False

            elif token == "(":
                function = (
                    tokens[index - 1]
                    if index and tokens[index - 1] in functions
                    else None
                )
                operators.append((function, len(operands)))
                need_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_one()
                need_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_one()
                function, start = operators.pop()
                if function is not None:
                    arguments = tuple(operands[start:])
                    del operands[start:]
                    operands.append((function, arguments))
                need_operand = False

            else:
                op = "neg" if token == "-" and need_operand else token
                while operators and isinstance(operators[-1], str):
                    previous = operators[-1]
                    if precedence[previous] < precedence[op]:
                        break
                    if precedence[previous] == precedence[op] and op == "neg":
                        break
                    reduce_one()
                operators.append(op)
                need_operand = True

        while operators:
            reduce_one()
        return operands[0]

    trees = {
        name: parse(content[1:]) if content.startswith("=") else integer(content)
        for name, content in cells.items()
    }

    def expand(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first, last = argument[1], argument[2]
                col1, col2 = ord(first[0]), ord(last[0])
                row1, row2 = int(first[1:]), int(last[1:])
                for row in range(min(row1, row2), max(row1, row2) + 1):
                    for col in range(min(col1, col2), max(col1, col2) + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield name
            else:
                yield argument

    results = {}
    active = set()
    end = object()

    # Explicit continuations avoid recursion for both expressions and references.
    for root in cells:
        if root in results:
            continue

        tasks = [("eval", root)]
        value = 0

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "eval":
                node = task[1]

                if isinstance(node, int):
                    value = node

                elif isinstance(node, str):
                    if node in results:
                        value = results[node]
                    elif node not in trees:
                        value = 0
                    elif node in active:
                        value = "#CYCLE!"
                    else:
                        active.add(node)
                        tasks.append(("save", node))
                        tasks.append(("eval", trees[node]))

                else:
                    op = node[0]
                    if op == "neg":
                        tasks.append(("negate",))
                        tasks.append(("eval", node[1]))
                    elif op == "IF":
                        condition, then_branch, else_branch = node[1]
                        tasks.append(("choose", then_branch, else_branch))
                        tasks.append(("eval", condition))
                    elif op in ("SUM", "MIN", "MAX"):
                        tasks.append(("fold", op, expand(node[1]), None))
                    else:
                        tasks.append(("left", op, node[2]))
                        tasks.append(("eval", node[1]))

            elif action == "save":
                results[task[1]] = value
                active.remove(task[1])

            elif action == "negate":
                if isinstance(value, int):
                    value = -value

            elif action == "left":
                if isinstance(value, int):
                    tasks.append(("right", task[1], value))
                    tasks.append(("eval", task[2]))

            elif action == "right":
                if isinstance(value, str):
                    continue

                op, left, right = task[1], task[2], value

                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        value = -quotient if (left < 0) != (right < 0) else quotient
                elif op == "=":
                    value = int(left == right)
                elif op == "<>":
                    value = int(left != right)
                elif op == "<":
                    value = int(left < right)
                elif op == "<=":
                    value = int(left <= right)
                elif op == ">":
                    value = int(left > right)
                elif op == ">=":
                    value = int(left >= right)

            elif action == "choose":
                if isinstance(value, int):
                    tasks.append(("eval", task[1] if value else task[2]))

            elif action == "fold":
                function, arguments, accumulated = task[1:]
                argument = next(arguments, end)
                if argument is end:
                    value = 0 if accumulated is None else accumulated
                else:
                    tasks.append(
                        ("fold_value", function, arguments, accumulated)
                    )
                    tasks.append(("eval", argument))

            elif action == "fold_value":
                if isinstance(value, str):
                    continue

                function, arguments, accumulated = task[1:]
                if accumulated is None:
                    accumulated = value
                elif function == "SUM":
                    accumulated += value
                elif function == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                tasks.append(("fold", function, arguments, accumulated))

    return {name: results[name] for name in cells}
